def transform(grid):
    h, w = len(grid), len(grid[0])
    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    components = []
    while remaining:
        stack = [remaining.pop()]
        component = set(stack)
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r + dr, c + dc)
                    if p in remaining:
                        remaining.remove(p)
                        component.add(p)
                        stack.append(p)
        components.append(component)

    # The desired figure is the smallest of the separated 8-connected figures.
    comp = min(components, key=lambda s: (
        (max(r for r, c in s) - min(r for r, c in s) + 1) *
        (max(c for r, c in s) - min(c for r, c in s) + 1)
    ))
    r0, r1 = min(r for r, c in comp), max(r for r, c in comp)
    c0, c1 = min(c for r, c in comp), max(c for r, c in comp)
    return [[grid[r][c] if (r, c) in comp else 0
             for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
